from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    # noise colors: colors with no connected object of size>=2 (4-connectivity)
    seen=[[False]*w for _ in range(h)]; sizes=Counter()
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; c=g[i][j]; n=0
                while st:
                    a,b=st.pop(); n+=1
                    for a2,b2 in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                        if 0<=a2<h and 0<=b2<w and not seen[a2][b2] and g[a2][b2]==c:
                            seen[a2][b2]=True; st.append((a2,b2))
                sizes[c]=max(sizes[c],n)
    noise={c for c,n in sizes.items() if n==1}
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j] in noise:
                nb=[g[a][b] for a,b in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=a<h and 0<=b<w]
                cnt=Counter(nb); m=max(cnt.values())
                cand=[k for k,v in cnt.items() if v==m]
                out[i][j]= cand[0] if len(cand)==1 else ([k for k in cand if k!=bg]+[bg])[0]
    return out
